$categories = [
    'All','Solar Battery','Battery','E-Rickshaw Lithium Battery','Cooler','AC','Chimney','Solar Panel','Home Inverter','High Capacity Inverter','3-Phase High Capacity Inverter','Grid Inverter','Hybrid Inverter','3-Phase Hybrid Inverter','3-Phase Lift Inverter','Solar Inverter','Washing Machine','Refrigerator','Room Heater','Accessory'
];
$category = trim((string)($_GET['category'] ?? 'All'));
if (!in_array($category, $categories, true)) $category = 'All';
$q = trim((string)($_GET['q'] ?? ''));
$sql = "SELECT * FROM products WHERE status='active'";
$params = [];
if ($category !== 'All') { $sql .= ' AND category = ?'; $params[] = $category; }
if ($q !== '') { $sql .= ' AND (name LIKE ? OR brand LIKE ? OR category LIKE ?)'; $like = '%' . $q . '%'; array_push($params, $like, $like, $like); }
$sql .= ' ORDER BY featured DESC, created_at DESC';
$stmt = db()->prepare($sql); $stmt->execute($params); $products = $stmt->fetchAll();
